// Maintenance cycle and reminders: the recurrence roll-forward done when a
// maintenance work order is completed, the overdue/upcoming alert queries shared
// by the dashboard and the daily job, and the in-app/email reminders.
const { notifyUser } = require('./notify');

// Look-ahead window (days) for "upcoming" maintenance and EPI expiry.
const UPCOMING_DAYS = 30;

// A work order counts as a maintenance one when it was generated by the
// scheduler or is due on the equipment's planned maintenance date.
//
// Called after a work order was moved to 'done'. Sets last_maintenance to the
// completion day and, when the equipment has a recurrence, moves
// next_maintenance to completion day + interval. Returns the updated equipment
// row, or null when nothing applied.
async function rollMaintenanceForward(db, workOrderId) {
  const { rows } = await db.query(
    `UPDATE equipment e
        SET last_maintenance = CURRENT_DATE,
            next_maintenance = CASE WHEN e.maintenance_interval_months IS NOT NULL
                                    THEN (CURRENT_DATE + make_interval(months => e.maintenance_interval_months))::date
                                    ELSE e.next_maintenance END,
            updated_at = NOW()
       FROM work_orders wo
      WHERE wo.id = $1
        AND wo.status = 'done'
        AND e.id = wo.equipment_id
        AND (wo.auto_generated = TRUE OR (wo.due_date IS NOT NULL AND wo.due_date = e.next_maintenance))
      RETURNING e.*`,
    [workOrderId]
  );
  return rows[0] || null;
}

// Equipment whose maintenance is overdue (next_maintenance < today) or due
// within `days` days. `days_until` is negative when overdue.
async function getMaintenanceAlerts(db, days = UPCOMING_DAYS) {
  const { rows } = await db.query(
    `SELECT e.id, e.name, e.client_id, c.name AS client_name, e.next_maintenance,
            (e.next_maintenance - CURRENT_DATE)::int AS days_until
       FROM equipment e JOIN clients c ON c.id = e.client_id
      WHERE e.next_maintenance IS NOT NULL
        AND COALESCE(e.status, 'active') <> 'inactive'
        AND e.next_maintenance <= CURRENT_DATE + $1::int
      ORDER BY e.next_maintenance, e.name`,
    [days]
  );
  return {
    overdue: rows.filter(r => r.days_until < 0),
    upcoming: rows.filter(r => r.days_until >= 0),
  };
}

// EPI (safety equipment) that is expired or expires within `days` days.
async function getEpiAlerts(db, days = UPCOMING_DAYS) {
  const { rows } = await db.query(
    `SELECT ep.id, ep.name, ep.client_id, c.name AS client_name, ep.expiry_date,
            (ep.expiry_date - CURRENT_DATE)::int AS days_until
       FROM epi ep JOIN clients c ON c.id = ep.client_id
      WHERE ep.expiry_date IS NOT NULL
        AND ep.expiry_date <= CURRENT_DATE + $1::int
      ORDER BY ep.expiry_date, ep.name`,
    [days]
  );
  return {
    expired: rows.filter(r => r.days_until < 0),
    expiring: rows.filter(r => r.days_until >= 0),
  };
}

// Creates one in-app notification per admin per
// alert kind, with the count in the message. Skipped when the same message was
// already sent to that admin in the last 7 days, so the daily job doesn't spam
// but a changed situation (different count) still notifies. Returns the number
// of notifications created.
async function sendReminderNotifications(db) {
  const [maint, epi, admins] = await Promise.all([
    getMaintenanceAlerts(db),
    getEpiAlerts(db),
    db.query("SELECT id FROM users WHERE role = 'admin'"),
  ]);

  // Email goes out through the admin digest (lib/digest.js), not from here.
  const items = [];
  const add = (type, label, list) => {
    if (list.length > 0) items.push({ type, message: `${label} : ${list.length}`, link: '/' });
  };
  add('maintenance_overdue', 'Maintenances en retard', maint.overdue);
  add('maintenance_upcoming', `Maintenances à venir (${UPCOMING_DAYS} j)`, maint.upcoming);
  add('epi_expired', 'EPI expirés', epi.expired);
  add('epi_expiring', `EPI bientôt expirés (${UPCOMING_DAYS} j)`, epi.expiring);

  let created = 0;
  for (const admin of admins.rows) {
    for (const item of items) {
      const dup = await db.query(
        `SELECT 1 FROM notifications WHERE user_id = $1 AND type = $2 AND message = $3
           AND created_at > NOW() - INTERVAL '7 days' LIMIT 1`,
        [admin.id, item.type, item.message]
      );
      if (dup.rows.length > 0) continue;
      await notifyUser(db, { userId: admin.id, ...item });
      created++;
    }
  }
  return created;
}

module.exports = { UPCOMING_DAYS, rollMaintenanceForward, getMaintenanceAlerts, getEpiAlerts, sendReminderNotifications };
